Add Row.code:
// Insert a row into a CARTO table.
addRow(
  // 1) Table name.
  'case_reports',
  // 2) Column values.
  {
    case_id: $.data.caseId,
    disease: $.data.disease,
    district: $.data.district,
    reported_on: $.data.reportedOn,
  }
);

Insert Point With SQL.code:
// Insert a geolocated row (PostGIS point) with SQL.
// `sql` takes a function that returns the query string.
sql(
  state => `INSERT INTO health_facilities (name, facility_type, the_geom)
  VALUES (
    '${state.data.name}',
    '${state.data.type}',
    ST_SetSRID(ST_MakePoint(${state.data.longitude}, ${state.data.latitude}), 4326)
  )`
);

Update Rows With SQL.code:
// Update a row's status with SQL.
sql(
  state => `UPDATE water_points
  SET status = '${state.data.status}', last_visit = '${state.data.visitDate}'
  WHERE water_point_id = '${state.data.waterPointId}'`
);

Query Rows Near a Point.code:
// Find facilities within 5 km of a point.
sql(
  state => `SELECT name, facility_type
  FROM health_facilities
  WHERE ST_DWithin(
    the_geom::geography,
    ST_SetSRID(ST_MakePoint(${state.data.longitude}, ${state.data.latitude}), 4326)::geography,
    5000
  )`
);

Aggregate by Area.code:
// Count case reports per district.
sql(
  state => `SELECT district, COUNT(*) AS cases
  FROM case_reports
  WHERE reported_on >= '${state.data.since}'
  GROUP BY district
  ORDER BY cases DESC`
);
